/* 组件就绪后执行 */
Eam.registerInit(async function(){
await (async()=>{if(!document.getElementById('order-selector'))return;const u=EamWorkUi,$=u.$,api=EamProblemApi,reviewPage=document.body.dataset.page==='acceptance';let order=null,config={},outcomeControls=[],residualControls=[],command='',busy=false,readToken=0,reading=false,commandTarget=null;
const orderId=()=>new URLSearchParams(location.search).get('order')||$('order-selector').value;
function render(){const o=order;const a=o.terminationApproval;$('order-approval-panel').hidden=!a;if(a){$('order-approval-summary').textContent=a.instanceId+' · 提交 '+EamProduct.time(a.submittedAt)+' · 申请V'+a.applicationRevision+' · '+({pending:'待审批',approved:'通过',rejected:'驳回',withdrawn:'撤回'}[a.status]||a.status)+' · '+(a.comment||'已提交')+' · '+(a.applyStatus==='blocked'?'业务待处理：'+a.applyError:a.applyStatus==='applied'?'已生效':'未生效');$('order-approval-refresh').hidden=!['engineer','supervisor'].includes(Eam.s.role);}$('order-content').hidden=false;$('order-number').textContent=o.id+' · 数据V'+o.version;$('order-title').textContent=o.title;$('order-scope').textContent=o.scope;$('order-status').replaceChildren(u.badge(o.status));u.facts($('order-facts'),[['执行人',u.name(o.assigneeId)],['执行版本','V'+o.executionVersion],['许可引用',o.permitId],['截止日期',o.dueAt||'未设置']]);for(const button of $('order-actions').querySelectorAll('[data-command]')){button.hidden=!o.actions.includes(button.dataset.command)||(reviewPage&&!['accept','close','cancel'].includes(button.dataset.command));}const editable=o.actions.includes('save')&&!reviewPage;$('execution-fields').disabled=!editable;$('save-execution').hidden=!editable;$('complete-execution').hidden=!editable;$('order-permission-note').textContent=o.reworkRequired?'验收已退回，原执行版本只读；由指派人员重新确认安全并开工。':['pending','approved'].includes(o.terminationApproval?.status)&&o.terminationApproval?.applyStatus!=='applied'?'终止审批处理中，冲突业务操作已冻结；请获取审批结果或更正申请。':!o.actions.length?'当前状态或权限只读。':'';$('outcome-mode').textContent=editable?'逐项填写本次结论及证据':'当前执行版本只读，问题状态来自独立流程';$('outcome-rows').replaceChildren();outcomeControls=[];
for(const p of o.relatedProblems){const saved=o.execution?.outcomes?.find(x=>x.kind===p.kind&&x.id===p.id),info=u.node('div');info.append(u.link(p.id+' · '+p.description,()=>u.openProblem(p.kind,p.id)),u.badge(p.status));const result=u.node('select');result.setAttribute('aria-label',p.id+'本次处理结论');for(const [value,label]of [['','选择逐项结论'],['resolved',u.label('resolved')],['unresolved',u.label('unresolved')],['not_applicable',u.label('not_applicable')]])result.add(new Option(label,value));result.value=saved?.result||'';result.disabled=!editable;const evidence=u.node('textarea');evidence.setAttribute('aria-label',p.id+'逐项证据');evidence.maxLength=2000;evidence.value=saved?.evidence||'';evidence.disabled=!editable;const time=u.node('input');time.type='datetime-local';time.setAttribute('aria-label',p.id+'功能恢复时间');time.value=saved?.restoredAt?.slice(0,16)||'';time.disabled=!editable||p.kind!=='failures';const last=p.kind==='failures'?time:u.node('span','不适用','muted');u.row($('outcome-rows'),[info,result,evidence,last],['问题 / 当前状态','本次结论','逐项证据','功能恢复时间']);outcomeControls.push({kind:p.kind,id:p.id,expectedProblemVersion:p.version,result,evidence,time});}
for(const [id,key]of [['execution-diagnosis','diagnosis'],['execution-measures','measures'],['execution-trial','trial'],['execution-labor','laborMinutes'],['execution-material','materialRef']])$(id).value=o.execution?.[key]??'';$('execution-history').replaceChildren();for(const revision of o.executionHistory){const details=u.node('details',undefined,'work-history');details.append(u.node('summary','执行V'+revision.revision+' · '+u.name(revision.executorId)+' · '+EamProduct.time(revision.completedAt)));details.append(u.node('p','诊断：'+revision.diagnosis),u.node('p','措施：'+revision.measures),u.node('p','试运行：'+revision.trial),u.node('p','实际工时：'+revision.laborMinutes+'分钟'));for(const item of revision.outcomes)details.append(u.node('p',item.id+' · '+u.label(item.result)+' · '+item.evidence));for(const a of o.acceptances.filter(a=>a.executionVersion===revision.revision))details.append(u.node('p',(a.decision==='pass'?'技术验收通过':'退回返工')+' · '+u.name(a.reviewerId)+' · '+a.reason));$('execution-history').append(details);}u.audit($('order-audit'),o.audit);const followups=document.getElementById('order-followups');if(followups){followups.replaceChildren();for(const a of o.terminationArrangements||[]){const item=u.node('div',undefined,'d-flex flex-wrap gap-2 align-items-center mb-2');item.append(u.node('span',a.id+' · '+u.name(a.ownerId)+' · 期限 '+a.dueAt+' · '+a.control),u.button(a.followupOrderId?'进入后续工单':'进入问题处置',()=>a.followupOrderId?Eam.go('order',{order:a.followupOrderId,equipment:o.equipmentId}):u.openProblem(a.kind,a.id)));followups.append(item);}document.getElementById('order-followup-panel').hidden=!o.terminationArrangements?.length;}}
async function load(id=orderId()){const token=++readToken;reading=true;$('order-content').inert=true;$('order-read-status').textContent='正在读取工单…';if(!id){$('order-content').hidden=true;reading=false;$('order-content').inert=false;$('order-read-status').textContent='请选择工单查看详情；验收队列不默认打开最后一条记录。';return;}try{const result=await api.request('GET','/work-orders/'+id);if(token!==readToken)return;EamArchiveContext.assertRecord(result,location.search);order=result;$('order-selector').value=id;render();$('order-read-status').textContent='已读取 '+id+' · V'+order.version;$('execution-error').textContent='';}catch(e){if(token!==readToken)return;$('order-content').hidden=true;$('order-read-status').textContent=e.message+'；旧工单仅保留历史来源，请从新工单列表选择。';}finally{if(token===readToken){reading=false;$('order-content').inert=false;}}}
const executionPayload=()=>({expectedVersion:order.version,reason:'提交执行记录',diagnosis:$('execution-diagnosis').value,measures:$('execution-measures').value,trial:$('execution-trial').value,laborMinutes:$('execution-labor').value,materialRef:$('execution-material').value,outcomes:outcomeControls.map(c=>({kind:c.kind,id:c.id,expectedProblemVersion:c.expectedProblemVersion,result:c.result.value,evidence:c.evidence.value,restoredAt:c.time.value}))});
async function execute(action){if(busy||reading||!order)return;busy=true;$('save-execution').disabled=$('complete-execution').disabled=true;try{await api.request('POST','/work-orders/'+order.id+'/'+action,executionPayload());await load(order.id);await refreshQueue();Eam.message(action==='complete'?'技术完成已提交；关联问题尚未关闭':'执行草稿已保存');}catch(e){$('execution-error').textContent=e.message+'；输入已保留，重新读取前请保存或记录草稿。';}finally{busy=false;$('save-execution').disabled=$('complete-execution').disabled=false;}}
async function openCommand(action){if(busy||reading||!order)return;commandTarget=JSON.parse(JSON.stringify(order));const target=commandTarget;command=action;target.residualRequired=action==='cancel'?target.terminationRequired:target.residualRequired;$('work-command-form').reset();$('command-error').textContent='';$('work-command-title').textContent=action==='cancel'?'提交终止申请':config.actionLabels[action];$('work-command-context').textContent=target.id+' · V'+target.version+' · 执行V'+target.executionVersion;for(const [id,show]of [['assign-field',action==='assign'],['safety-fields',action==='start'],['accept-fields',action==='accept'],['residual-fields',['close','cancel'].includes(action)&&target.residualRequired.length>0],['site-restored-field',action==='cancel'&&target.executionVersion>0],['command-evidence-field',action==='cancel'&&target.executionVersion>0]])$(id).hidden=!show;const permit=config.permits.find(p=>p.id===target.permitId);$('permit-summary').textContent=(permit?.name||'未绑定许可')+' · 有效期 '+EamProduct.time(permit?.validUntil);$('residual-list').replaceChildren();residualControls=[];
if(['close','cancel'].includes(action)&&target.residualRequired.length){try{const followups=(await api.request('GET','/work-orders')).rows,people=(await api.request('GET','/people')).rows;for(const ref of target.residualRequired){const p=target.relatedProblems.find(p=>p.kind===ref.kind&&p.id===ref.id),block=u.node('section',undefined,'work-residual');block.append(u.node('h3',ref.id+' · '+p.description));const eligible=followups.filter(o=>o.id!==target.id&&!['draft','closed','cancelled'].includes(o.status)&&o.problemRefs.some(p=>p.kind===ref.kind&&p.id===ref.id));const followup=u.field(block,action==='cancel'?'承接方式 / 后续工单':'已审核后续工单 *','select',[{value:'',label:action==='cancel'?'问题责任人直接承接，后续可建单':'请选择'},...eligible.map(o=>({value:o.id,label:o.id+' '+o.title}))]);const owner=u.field(block,'后续主责 *','select',[{value:'',label:'请选择责任人'},...people.filter(p=>action!=='cancel'||config.followupOwnerIds.includes(p.id)).map(p=>({value:p.id,label:p.name}))]);const due=u.field(block,'后续期限 *','date'),control=u.field(block,'控制措施 / 批准依据 *','textarea'),until=u.field(block,'控制有效期 *','datetime-local');followup.required=action==='close';owner.required=due.required=control.required=until.required=true;control.maxLength=2000;$('residual-list').append(block);residualControls.push({kind:ref.kind,id:ref.id,expectedProblemVersion:p.version,followup,owner,due,control,until});}}catch(e){Eam.message(e.message);return;}}
$('work-command-dialog').showModal();}
$('work-command-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('command-submit').disabled=true;const body={expectedVersion:commandTarget.version,reason:$('command-reason').value,assigneeId:$('assign-person').value,isolation:$('safe-isolation').checked,guard:$('safe-guard').checked,decision:$('accept-decision').value,trialConfirmed:$('trial-confirmed').checked,siteRestored:$('site-restored').checked,evidence:$('command-evidence').value,residuals:residualControls.map(c=>({kind:c.kind,id:c.id,expectedProblemVersion:c.expectedProblemVersion,followupOrderId:c.followup.value,ownerId:c.owner.value,dueAt:c.due.value,control:c.control.value,controlUntil:c.until.value}))};try{await api.request('POST','/work-orders/'+commandTarget.id+'/'+(command==='cancel'?'termination-applications':command),{...body,idempotencyKey:commandTarget.id+'-termination-'+commandTarget.version});$('work-command-dialog').close();await load(commandTarget.id);await refreshQueue();Eam.message(command==='accept'?'验收决定已保存；问题验证与专业放行仍独立':'工单操作已保存');}catch(error){$('command-error').textContent=error.message+'；表单输入已保留。取消后重新读取可比较最新状态。';}finally{busy=false;$('command-submit').disabled=false;}};
async function refreshQueue(){const all=EamArchiveContext.filter((await api.request('GET','/work-orders')).rows,location.search);$('order-selector').replaceChildren(new Option('请选择工单',''));const visible=reviewPage?all.filter(o=>['technical_complete','accepted'].includes(o.status)):all;for(const o of visible)$('order-selector').add(new Option(o.id+' · '+o.title+' · '+u.label(o.status),o.id));if(order)$('order-selector').value=order.id;if($('review-queue')){$('review-queue').replaceChildren();for(const o of visible)u.row($('review-queue'),[o.id+' · '+o.title,u.badge(o.status),u.name(o.assigneeId)+' / V'+o.executionVersion,u.button('查看与处理',()=>select(o.id))],['工单','状态','执行人 / 版本','操作']);$('review-queue-empty').hidden=!!visible.length;}}
async function select(id){const url=new URL(location.href);url.searchParams.set('order',id);history.replaceState(null,'',url);await load(id);}
$('order-approval-refresh').onclick=async()=>{if(busy||reading||!order?.terminationApproval)return;busy=true;$('order-approval-refresh').disabled=true;try{const a=order.terminationApproval;await api.request('GET','/approval-adapter/instances/'+a.instanceId+'/result',{sample:$('order-approval-sample').value});await api.request('POST','/work-orders/'+order.id+'/apply-approval-result',{instanceId:a.instanceId,applicationRevision:a.applicationRevision,sample:$('order-approval-sample').value});await load(order.id);await refreshQueue();$('order-approval-error').textContent='';}catch(e){$('order-approval-error').textContent=e.message;}finally{busy=false;$('order-approval-refresh').disabled=false;}};
$('order-selector').onchange=e=>select(e.target.value);$('order-refresh').onclick=()=>load();$('save-execution').onclick=()=>execute('save');$('complete-execution').onclick=()=>execute('complete');$('command-cancel').onclick=()=>$('work-command-dialog').close();for(const b of $('order-actions').querySelectorAll('[data-command]'))b.onclick=()=>openCommand(b.dataset.command);
try{config=await u.init();for(const p of config.executors)$('assign-person').add(new Option(p.name,p.id));await refreshQueue();await load();}catch(e){$('order-read-status').textContent=e.message;}
})();

});
